package com.aoo.bcg.common.invite;
import java.time.Instant;import java.util.Map;import java.util.concurrent.ConcurrentHashMap;
/** Immediate revocation index for lifecycle and authority changes. */
public final class InviteRevocationRegistry{public enum Reason{ROOM_ENDED,TEMPLATE_DELETED,INVITER_PERMISSION_REVOKED,MANUAL}public record Entry(String inviteId,long roomId,long templateId,long inviterId,Instant expiresAt,Reason revokedReason){}private final ConcurrentHashMap<String,Entry>entries=new ConcurrentHashMap<>();public void register(String inviteId,long roomId,long templateId,long inviterId,Instant expiresAt){if(inviteId==null||inviteId.isBlank()||roomId<=0||templateId<0||inviterId<=0||expiresAt==null)throw new IllegalArgumentException("invalid invite registration");if(entries.putIfAbsent(inviteId,new Entry(inviteId,roomId,templateId,inviterId,expiresAt,null))!=null)throw new IllegalStateException("invite already registered");}public boolean active(String inviteId,Instant now){Entry entry=entries.get(inviteId);return entry!=null&&entry.revokedReason()==null&&now.isBefore(entry.expiresAt());}public void roomEnded(long roomId){revoke(entry->entry.roomId()==roomId,Reason.ROOM_ENDED);}public void templateDeleted(long templateId){revoke(entry->entry.templateId()==templateId,Reason.TEMPLATE_DELETED);}public void inviterPermissionRevoked(long inviterId){revoke(entry->entry.inviterId()==inviterId,Reason.INVITER_PERMISSION_REVOKED);}public Map<String,Entry>snapshot(){return Map.copyOf(entries);}private void revoke(java.util.function.Predicate<Entry>predicate,Reason reason){entries.replaceAll((id,entry)->predicate.test(entry)&&entry.revokedReason()==null?new Entry(entry.inviteId(),entry.roomId(),entry.templateId(),entry.inviterId(),entry.expiresAt(),reason):entry);}}
